// 429 TPM with retry-after. Run A's first send is rejected (invalid_encrypted_content), so A
// resends inside its already admitted call, the way the Responses transport replays.
// Requests go through the real OpenAI SDK, buildGuardedModelFetch, admitProviderRateLimitStream
// and projectProviderError. No real provider account is used.
import http from "node:http";
import type { AddressInfo } from "node:net";
import OpenAI from "openai";
import { projectProviderError } from "../packages/ai/src/utils/provider-error.js";
import { buildGuardedModelFetch } from "../src/agents/provider-transport-fetch.js";
import { admitProviderRateLimitStream } from "../src/llm/provider-rate-limit-stream.js";
import type { AssistantMessage, Model } from "../src/llm/types.js";
import { createAssistantMessageEventStream } from "../src/llm/utils/event-stream.js";

const label = process.argv[2] ?? "run";
const RETRY_AFTER_S = 3;
const INLINE_KEY = "sk-proof-inline-synthetic-key";
const t0 = Date.now();
const log = (line: string) =>
