let deadlineAt = 0;
let heldA1: http.ServerResponse | undefined;
let onA1Held: (() => void) | undefined;
let sends = 0;

const stub = http.createServer((req, res) => {
  let body = "";
  req.on("data", (chunk) => (body += chunk));
  req.on("end", () => {
    sends += 1;
    const run = /RUN-(A1|A2|B)/.exec(body)?.[1] ?? "?";
    const auth = req.headers.authorization === `Bearer ${INLINE_KEY}` ? "inline-key" : "other";
    const timing =
      deadlineAt === 0
        ? ""
        : Date.now() < deadlineAt
          ? ` (${deadlineAt - Date.now()}ms BEFORE the shared deadline)`
          : ` (${Date.now() - deadlineAt}ms after the shared deadline)`;
    log(`stub <- POST ${req.url} run=${run} auth=${auth}${timing}`);
    const json = (status: number, payload: unknown, headers: Record<string, string> = {}) => {
      res.writeHead(status, { "content-type": "application/json", ...headers });
      res.end(JSON.stringify(payload));
    };
    if (run === "A1") {
      heldA1 = res;
      onA1Held?.();
      return;
    }
    if (deadlineAt === 0 || Date.now() < deadlineAt) {
      if (deadlineAt === 0) {
        deadlineAt = Date.now() + RETRY_AFTER_S * 1000;
      }
      const left = Math.ceil((deadlineAt - Date.now()) / 1000);
      log(`stub -> run=${run}: 429 rate_limit_exceeded, retry-after: ${left}`);
      return json(
        429,
        {
          error: {
            message: `Rate limit reached for stub-model in organization org-proof on tokens per min (TPM): Limit 1000, Used 1000, Requested 50. Please try again in ${left}s.`,
            type: "tokens",
            param: null,
            code: "rate_limit_exceeded",
          },
        },
        { "retry-after": String(left) },
      );
    }
    log(`stub -> run=${run}: 200 completed`);
    return json(200, {
      id: `resp_proof_${sends}`,
      object: "response",
      status: "completed",
      model: "stub-model",
      output: [],
    });
  });
});

function terminal(model: Model, fields: Partial<AssistantMessage>): AssistantMessage {
  return {
    role: "assistant",
    content: [],
    api: model.api,
    provider: model.provider,
    model: model.id,
    usage: {
      input: 0,
      output: 0,
      cacheRead: 0,
      cacheWrite: 0,
      totalTokens: 0,
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
